def media(numeros):
    if not numeros:
        return 0
    return sum(numeros) / len(numeros)

def contar_falhas(linhas):
    total = 0
    for linha in linhas:
        if "FALHA" in linha:
            total += 1
    return total

def mascarar_cartao(numero):
    if len(numero) <= 4:
        return "*" * len(numero)
    return "*" * (len(numero) - 4) + numero[-4:]

import re

def formato_cpf(texto):
    if not texto:
        return False
    return bool(re.fullmatch(r"\d{3}\.\d{3}\.\d{3}-\d{2}", texto))

def top_ips(linhas, n):
    contagem = {}
    for linha in linhas:
        partes = linha.split()
        if len(partes) < 4:
            continue
        ip = partes[3]
        contagem[ip] = contagem.get(ip, 0) + 1

    ordenado = sorted(contagem.items(), key=lambda par: par[1], reverse=True)
    return [ip for ip, _ in ordenado[:n]]

def tem_sequencia(senha):
    if len(senha) < 3:
        return False
    for i in range(len(senha) - 2):
        a, b, c = senha[i], senha[i+1], senha[i+2]
        if ord(b) - ord(a) == 1 and ord(c) - ord(b) == 1:
            return True
    return False
